using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var researchTools = new ResearchTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.AddNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// --- Chat client -------------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Agent -------------------------------------------------------------------

const string instructions = """
    You are a research assistant. When given a topic you MUST:
    1. Search the web multiple times with different queries to gather diverse information.
    2. As you find useful facts, save each one as a note using the note-taking tool.
    3. After collecting enough notes (at least 3-5), retrieve all your notes.
    4. Produce a well-structured summary of the topic based on your notes.
    Always cite the source URL for each piece of information.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic using web search and compiles a summary.",
    tools: tools);

// --- Run ---------------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MAF + MEAI)       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    topic = "Recent advances in quantum computing";
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    options: null);

Console.WriteLine();
Console.WriteLine(response.Text);
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Notes collected: {researchTools.NoteCount}");

