// Tool implementations
// =============================================================================

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no API key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _httpClient.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();

            var resultCount = 0;

            // Abstract / instant answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"**{abstractSource}**: {abstractText}");
                sb.AppendLine($"  URL: {abstractUrl}");
                sb.AppendLine();
                resultCount++;
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var item in relatedTopics.EnumerateArray())
                {
                    if (resultCount >= 5) break;
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(firstUrl))
                            sb.AppendLine($"  URL: {firstUrl}");
                        sb.AppendLine();
                        resultCount++;
                    }
                }
            }

            if (resultCount == 0)
            {
                sb.AppendLine("No results found. Try rephrasing the query.");
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important facts or findings as you research.")]
    public string AddNote(
        [Description("The note content to save, including source attribution")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} notes");
        var sb = new StringBuilder();
        sb.AppendLine($"All saved notes ({_notes.Count}):");
        sb.AppendLine();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"{i + 1}. {_notes[i]}");
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

